-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/models/silver/silver_practitioner.sql. Do not edit.
-- Silver practitioner: one row per member of staff, deduplicated on resource id.
CREATE OR REPLACE TABLE silver_practitioner AS
WITH latest AS (
    SELECT *
    FROM bronze_resources
    WHERE resource_type = 'Practitioner'
    QUALIFY ROW_NUMBER() OVER (PARTITION BY resource_id ORDER BY loaded_at DESC, bronze_id DESC) = 1
),
typed AS (
    SELECT
        resource_id                                                    AS practitioner_id,
        -- Synthea appends digits to names (Bergstrom287), as it does for patients
        REGEXP_REPLACE(raw:name[0].family::string, '[0-9]+$', '')     AS family_name,
        REGEXP_REPLACE(raw:name[0].given[0]::string, '[0-9]+$', '')   AS given_name,
        raw:name[0].prefix[0]::string                                 AS prefix,
        raw:identifier[0].system::string                              AS identifier_system,
        raw:identifier[0].value::string                               AS identifier_value,
        source_file,
        loaded_at
    FROM latest
)
SELECT
    practitioner_id,
    family_name,
    given_name,
    prefix,
    TRIM(COALESCE(prefix || ' ', '') || COALESCE(given_name || ' ', '') || COALESCE(family_name, ''))  AS display_name,
    identifier_system,
    identifier_value,
    source_file,
    loaded_at
FROM typed;
